<?php declare(strict_types=1); ?>
<div class="grid-2"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Advance shipment notice</span><h2>Submit ASN</h2></div></header><?php if(supplier_portal_can($account,'submit_asn')&&$selectedPo): ?><form class="form-grid" method="post" action="<?= h(root_url('supplier-portal/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="submit_asn"><input type="hidden" name="return_tab" value="shipments"><label><span>Purchase order</span><select name="purchase_order_id" onchange="location.href='?tab=shipments&po_id='+this.value"><?php foreach($pos as $po): ?><option value="<?= (int)$po['id'] ?>" <?= $selectedPoId===(int)$po['id']?'selected':'' ?>><?= h($po['po_number']) ?></option><?php endforeach; ?></select></label><label><span>PO line</span><select name="purchase_order_line_id"><?php foreach($poLines as $line): ?><option value="<?= (int)$line['id'] ?>"><?= h(($line['description']??'Line').' · '.($line['quantity_ordered']??$line['quantity']??0)) ?></option><?php endforeach; ?></select></label><label><span>ASN number</span><input name="asn_number" required></label><label><span>Quantity shipped</span><input type="number" name="quantity_shipped" min="0.0001" step="0.0001" required></label><label><span>Ship date</span><input type="date" name="ship_date" value="<?= date('Y-m-d') ?>" required></label><label><span>Estimated arrival</span><input type="date" name="estimated_arrival" value="<?= date('Y-m-d',strtotime('+3 days')) ?>" required></label><label><span>Carrier</span><input name="carrier" required></label><label><span>Tracking number</span><input name="tracking_number" required></label><label><span>Packages</span><input type="number" name="package_count" min="0" value="1"></label><label><span>Pallets</span><input type="number" name="pallet_count" min="0" value="0"></label><label><span>Packing slip</span><input name="packing_slip_reference" required></label><label><span>Lot / serial</span><input name="lot_or_serial_reference"></label><label><span>Package reference</span><input name="package_reference"></label><label class="span-2"><span>Shipment notes</span><textarea name="notes"></textarea></label><div class="span-2"><button class="button primary">Submit ASN</button></div></form><?php else: ?><div class="empty">No shipment permission or authorized purchase order.</div><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Shipment history</span><h2>Submitted ASNs</h2></div></header><div class="record-list"><?php foreach($asns as $asn): ?><article class="record-card"><header><div><strong><?= h($asn['asn_number']) ?></strong><small><?= h($asn['carrier']) ?> · <?= h($asn['tracking_number']) ?></small></div><span class="status <?= h($asn['status']) ?>"><?= h(status_label($asn['status'])) ?></span></header><p>Ships <?= h(date_us($asn['ship_date'])) ?> · Estimated <?= h(date_us($asn['estimated_arrival'])) ?></p></article><?php endforeach; ?></div></section></div>
